import React, { useState } from 'react';

const BUTTONDOWN_URL = 'https://buttondown.email/api/emails/embed-subscribe/bagwala';

export default function NewsletterPanel() {
  const [email, setEmail] = useState('');
  const [status, setStatus] = useState('idle'); // idle | loading | success | error

  async function handleSubmit(e) {
    e.preventDefault();
    setStatus('loading');
    try {
      const data = new FormData();
      data.append('email', email);
      const res = await fetch(BUTTONDOWN_URL, { method: 'POST', body: data });
      if (res.ok || res.status === 302 || res.redirected) {
        setStatus('success');
      } else {
        setStatus('error');
      }
    } catch {
      setStatus('error');
    }
  }

  return (
    <div className="panel newsletter">
      <div className="panel-title">Depth First</div>
      <p className="panel-body">
        Once a month: AI in practice, engineering craft, and lessons from a decade of shipping software.
      </p>
      {status === 'success' ? (
        <p style={{ marginTop: 16, fontSize: 13, color: 'rgba(255,255,255,0.8)', lineHeight: 1.5 }}>
          You're in. Check your inbox to confirm.
        </p>
      ) : (
        <form className="news-form" onSubmit={handleSubmit}>
          <input
            type="email"
            name="email"
            placeholder="you@domain.com"
            required
            value={email}
            onChange={e => setEmail(e.target.value)}
            disabled={status === 'loading'}
          />
          <button type="submit" disabled={status === 'loading'}>
            {status === 'loading' ? '...' : 'Subscribe'}
          </button>
        </form>
      )}
      {status === 'error' && (
        <p style={{ marginTop: 8, fontSize: 12, color: 'rgba(255,255,255,0.6)' }}>
          Something went wrong. Try again or subscribe at buttondown.email/bagwala
        </p>
      )}
    </div>
  );
}
