import React from 'react';
import { graphql, useStaticQuery } from 'gatsby';

export default function ThreadPanel() {
  const data = useStaticQuery(graphql`
    query ThreadPanelQuery {
      allThreadsJson(sort: { date: DESC }, limit: 1) {
        nodes { date handle url tweets { body likes rts age } }
      }
    }
  `);
  const thread = data.allThreadsJson?.nodes[0];
  if (!thread) return null;
  return (
    <div className="panel">
      <div className="panel-title">Latest thread</div>
      <div className="panel-sub">{thread.handle}</div>
      <ol className="thread">
        {thread.tweets.map((t, i) => (
          <li key={i} className="tweet">
            <p className="tweet-text">{t.body}</p>
            <div className="tweet-meta">♡ {t.likes} · ↻ {t.rts}</div>
          </li>
        ))}
      </ol>
      <a href={thread.url} className="panel-cta" rel="noopener noreferrer">View on X →</a>
    </div>
  );
}
