import React from 'react';
import { graphql, useStaticQuery } from 'gatsby';
import AboutPanel from './AboutPanel';
import ThreadPanel from './ThreadPanel';
import NowPanel from './NowPanel';
import CategoryPanel from './CategoryPanel';
import NewsletterPanel from './NewsletterPanel';

export default function Sidebar({ activeCategory, onPickCategory, categoryCounts }) {
  const data = useStaticQuery(graphql`
    query SidebarQuery { site { siteMetadata { sidebarMode } } }
  `);
  const mode = data.site.siteMetadata.sidebarMode;
  return (
    <aside className="side">
      {mode === 'about'   && <AboutPanel />}
      {mode === 'twitter' && <ThreadPanel />}
      {mode === 'now'     && <NowPanel />}
      <NewsletterPanel />
      <CategoryPanel
        categories={categoryCounts}
        active={activeCategory}
        onPick={onPickCategory}
      />
    </aside>
  );
}
