import React from 'react';

export default function SearchBar({ value, onChange, resultCount, activeCategory, onClearCategory }) {
  return (
    <div className="search-wrap">
      <input
        type="search"
        className="search-input"
        placeholder="Search essays…"
        value={value}
        onChange={e => onChange(e.target.value)}
      />
      {(value || (activeCategory && activeCategory !== 'All')) && (
        <div className="search-meta">
          <span>{resultCount} result{resultCount !== 1 ? 's' : ''}</span>
          {activeCategory && activeCategory !== 'All' && (
            <button className="clear-cat" onClick={onClearCategory}>
              {activeCategory} ×
            </button>
          )}
        </div>
      )}
    </div>
  );
}
