import React, { useState, useMemo } from 'react';
import { graphql } from 'gatsby';
import Layout from '../components/Layout';
import Intro from '../components/Intro';
import SearchBar from '../components/SearchBar';
import CategoryRail from '../components/CategoryRail';
import PostList from '../components/PostList';
import Sidebar from '../components/Sidebar';

export default function IndexPage({ data }) {
  const [q,   setQ]   = useState('');
  const [cat, setCat] = useState('All');

  const posts = data.allMdx.nodes.map(n => ({
    slug:     `/posts${n.fields.slug}/`,
    title:    n.frontmatter.title,
    date:     n.frontmatter.date,
    category: n.frontmatter.category,
    dek:      n.frontmatter.dek,
    readTime: n.fields.readTime,
    featured: n.frontmatter.featured,
    coverUrl: n.frontmatter.coverUrl || null,
  }));

  const categoryCounts = data.allMdx.group.map(g => ({ name: g.fieldValue, count: g.totalCount }));

  const filtered = useMemo(() => {
    let list = posts;
    if (cat !== 'All') list = list.filter(p => p.category === cat);
    if (q.trim()) {
      const t = q.toLowerCase();
      list = list.filter(p => (p.title + ' ' + p.dek).toLowerCase().includes(t));
    }
    return list;
  }, [posts, cat, q]);

  return (
    <Layout active="articles">
      <Intro
        eyebrow="Est. 2017 · Essays, notes, and code"
        title={`Software craftsman <span class="intro-dim">writing about</span> AI, Distributed Systems, <span class="intro-dim">and the</span> slow work <span class="intro-dim">of thinking well.</span>`}
        essayCount={posts.length}
        updatedAt={posts[0]?.date}
      />
      <div className="main">
        <div>
          <SearchBar
            value={q}
            onChange={setQ}
            resultCount={filtered.length}
            activeCategory={cat !== 'All' ? cat : null}
            onClearCategory={() => setCat('All')}
          />
          <CategoryRail
            categories={categoryCounts}
            active={cat}
            onPick={setCat}
          />
          <PostList posts={filtered} />
        </div>
        <Sidebar
          activeCategory={cat}
          onPickCategory={setCat}
          categoryCounts={categoryCounts}
        />
      </div>
    </Layout>
  );
}

export const query = graphql`
  query IndexPageQuery {
    allMdx(
      filter: { frontmatter: { draft: { ne: true } } }
      sort: { frontmatter: { date: DESC } }
    ) {
      nodes {
        fields { slug readTime }
        frontmatter {
          title
          date(formatString: "MMMM YYYY")
          category
          dek
          featured
          coverUrl
        }
      }
      group(field: { frontmatter: { category: SELECT } }) {
        fieldValue
        totalCount
      }
    }
  }
`;
