import React from 'react';
import { graphql, useStaticQuery } from 'gatsby';

export default function AboutPanel() {
  const data = useStaticQuery(graphql`
    query AboutPanelQuery {
      site { siteMetadata {
        author { name short bio avatar }
        social { platform url }
      }}
    }
  `);
  const { author, social } = data.site.siteMetadata;
  return (
    <div className="panel">
      <img
        src={author.avatar}
        alt={author.name}
        style={{ width: 64, height: 64, borderRadius: '50%', objectFit: 'cover', marginBottom: 12, display: 'block' }}
      />
      <div className="panel-title">Hi, I'm {author.name.split(' ')[0]}.</div>
      <p className="panel-body">{author.bio}</p>
      <div className="about-links">
        {social.map(s => (
          <a key={s.platform} href={s.url} rel="me noopener noreferrer">{s.platform}</a>
        ))}
      </div>
    </div>
  );
}
