import React from 'react';

export default function CategoryRail({ categories, active, onPick, overflowAt = 10 }) {
  const total   = categories.reduce((s, c) => s + c.count, 0);
  const visible = categories.slice(0, overflowAt);
  return (
    <div className="cat-rail">
      <div className="cat-rail-inner">
        <button
          className={'cat-chip ' + (active === 'All' ? 'on' : '')}
          onClick={() => onPick('All')}
        >
          All <span>{total}</span>
        </button>
        {visible.map(c => (
          <button
            key={c.name}
            className={'cat-chip ' + (active === c.name ? 'on' : '')}
            onClick={() => onPick(c.name)}
          >
            {c.name} <span>{c.count}</span>
          </button>
        ))}
      </div>
    </div>
  );
}
